mapper.select:
SELECT INSTITUTION_ID
  FROM INSTITUTIONS
 WHERE NAME_KO = #{nameKo}

mapper.update:
UPDATE INSTITUTIONS
REGION_CODE = #{upd.regionCode,jdbcType=VARCHAR}, TYPE = #{upd.type,jdbcType=VARCHAR}, CONTRACT_END = #{upd.contractEnd,jdbcType=VARCHAR}, LAST_BID = #{upd.lastBid,jdbcType=VARCHAR}, TERM = #{upd.term,jdbcType=DECIMAL},
WHERE INSTITUTION_ID = #{institutionId}

UPDATE INSTITUTIONS
   SET GIGANLIST_DIR = #{giganlistDir,jdbcType=VARCHAR}
 WHERE INSTITUTION_ID = #{institutionId}

UPDATE INSTITUTIONS
   SET RFP_PATH = #{rfpPath,jdbcType=VARCHAR}
 WHERE INSTITUTION_ID = #{institutionId}

UPDATE INSTITUTIONS
   SET PPTX_PATH = #{pptxPath,jdbcType=VARCHAR}
 WHERE INSTITUTION_ID = #{institutionId}
